        pair.second = false;
        pair.first = in.ReadString();
        TransferBinaryIn(in, &pair.second);
        out.insert(Pair(pair.first, pair.second));
    }
}

int main()
{
    static const unsigned char buf[] = { 3, 0, 0, 0, 2, 'h', 'i', 1, 3, 'f', 'o', 'o', 0, 2, 'h', 'i', 0 };
